<script setup lang="tsx">
import { ref, computed, watch, onMounted, onBeforeUnmount } from "vue";
import { useRoute } from "vue-router";
import router from "@/router";
import {
  GetProblemJudge,
  PostJudgeDataAi,
  GetJudgeDataAi,
  GetJudgeDataAiList,
  GetAiPreviewZip,
  PostJudgeDataAiApply,
  PostJudgeDataAiCancel,
  PostJudgeDataAiRetry,
} from "@/apis/problem.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import { useWebStyleStore } from "@/stores/webStyle.ts";
import { AiTestdataJobView, AiTestdataStageView, AiTestdataLlmCallView } from "@/types/problem.ts";
import { GetFileSizeStr } from "@/util/file.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

let route = useRoute();
const { globalProperties } = useCurrentInstance();

const webStyleStore = useWebStyleStore();
const { isMobile } = useBreakpoint();

// ===== 题目信息（精简加载：仅取 id / 标题 / AI 开关 / 最近任务；权限由路由 auths 兜底） =====
const problemKey = ref("");
let problemId = 0;
const problemTitle = ref("");
const problemLoading = ref(false);
const aiEnabled = ref(false);

// ===== AI 生成测试数据 =====
const AI_STATUS_NAMES: Record<number, string> = {
  0: "等待开始",
  1: "排队中",
  2: "规划测试点",
  3: "撰写参考代码",
  4: "编译参考代码",
  5: "生成输入数据",
  6: "运行参考代码",
  7: "已完成",
  8: "生成失败",
  9: "已取消",
};

const aiHint = ref("");
const aiJobList = ref<AiTestdataJobView[]>([]);
const aiListLoading = ref(false);
const aiSelectedJobId = ref(0);
const aiJob = ref<AiTestdataJobView | null>(null);
const aiCreating = ref(false);
const aiApplying = ref(false);
const aiApplyDialogVisible = ref(false);
const aiDownloading = ref(false);
// 失败详情弹窗：表格内只展示短标签，完整报错点击后弹窗查看（避免长文本撑宽表格）
const aiErrorDialogVisible = ref(false);
const aiErrorDialogTitle = ref("");
const aiErrorDialogText = ref("");
let aiTimer = -1 as any;
let aiFetchSeq = 0; // 拉取世代计数：放弃任务/卸载组件时自增，使在途请求的响应作废

// 提示词快捷预设：点击后填入文本框。
// 设计约束：这些文案会被当作规划阶段的「用户偏好」叠加在系统提示词之上，
// 因此要（1）彼此独立、（2）不写死与题面冲突的具体数值（如写死 n=10^5 可能与真实限制打架）、
// （3）聚焦"规划侧重"（hint 只在规划阶段生效，不影响生成器/校验器写法）
const hintPresets = [
  {
    label: "边界覆盖",
    text: "覆盖每个约束维度的边界值：n 取最小值（如 n=1）与恰好达到题目数据范围上限两个极端，再补 2~3 个临界值附近的数据",
  },
  {
    label: "最坏构造",
    text: "加入能卡到算法最坏时间复杂度与最大常数的最坏情况构造（如已排序/逆序、全部元素相同、链式结构等），用于区分算法复杂度",
  },
  {
    label: "分级大规模",
    text: "按规模分级铺开：覆盖题目允许的最大规模（如 n/m 取上限）与 2~3 个中等规模随机点，大规模点标注明确规模供生成器使用",
  },
  {
    label: "控制数量",
    text: "测试点数量控制在 10~14 个，减少冗余低价值点，分数集中在边界与最坏构造点",
  },
];

const applyHintPreset = (text: string) => {
  aiHint.value = text;
};

const aiStatusName = computed(() => {
  if (!aiJob.value) return "";
  return AI_STATUS_NAMES[aiJob.value.status] ?? "未知";
});

const aiIsRunning = computed(() => {
  return aiJob.value !== null && aiJob.value.status <= 6;
});

const aiIsFinished = computed(() => {
  return aiJob.value !== null && aiJob.value.status === 7;
});

const aiProgressPercent = computed(() => {
  if (!aiJob.value || aiJob.value.task_total <= 0) return 0;
  return Math.min(99, Math.floor((aiJob.value.task_current / aiJob.value.task_total) * 100));
});

// 任务表格数据：把 result.tasks 映射为文件元数据列需要的字段（文件名/大小/输出限制）
const aiTasks = computed(() =>
  (aiJob.value?.result?.tasks ?? []).map((t) => ({
    ...t,
    score: t.score ?? 0,
    inFile: `${t.key}.in`,
    inFileSize: t.in_file_size ?? 0,
    outFile: `${t.key}.out`,
    outFileSize: t.out_file_size ?? 0,
    outLimit: t.out_limit ?? 0,
  }))
);

const aiSuccessCount = computed(() => aiTasks.value.filter((t) => t.status === "accepted").length);

const aiHasFailedTasks = computed(() => aiTasks.value.some((t) => t.status !== "accepted"));

// 预览数据是否已过期（R2 存储对象被清理）：过期后下载/应用/重试均需重新生成
const aiFileExpired = computed(() => aiJob.value?.file_expired === true);

// 重试作用域：全部失败测试点（重试所有未通过的点）
const aiFailedKeys = computed(() => aiTasks.value.filter((t) => t.status !== "accepted").map((t) => t.key));

// 阶段时间线数据：任务进行中时依赖 aiNow，每 100ms tick 重建（浅克隆阶段对象）。
// 仅靠外部 ref 变化无法可靠穿透 TDesign 组件层级：Vue 的 shouldUpdateComponent
// 对 props 做浅比较（st 对象引用不变则跳过子树），t-table 还可能按行对象缓存 cell；
// 实测只有数据身份变化（如轮询返回新对象）才会刷新，因此这里主动改变对象身份
const aiStages = computed(() => {
  const stages = aiJob.value?.stages ?? [];
  if (!aiIsRunning.value) return stages;
  void aiNow.value; // 依赖 aiNow：tick 时重建数组与阶段对象
  return stages.map((st) => ({ ...st }));
});

// 当前时间（running 阶段实时计算已用时长）
const aiNow = ref(Date.now());
let aiLastWall = Date.now();
let aiTickTimer = -1 as any;

// 判题机时钟偏差持久化（localStorage，按判题机名的「客户端-判题机」主键）：
// modify_time/start_time 由判题机以其本地时钟写入，与客户端/Web 服务器时钟存在固定偏差（本环境约 +154s）。
// 单次 modify_time 采样会落后（心跳仅 30s、阶段切换才刷新），得到的是偏差下界；这里取历史最大采样逼近
// 真实偏差并跨刷新保留——刷新后首帧就能用已知偏差换算出真实历史耗时，而不是从数据库落盘点（可能陈旧的
// modify_time）重新起算；不同判题机时钟不同，故按判题机名分桶，24h 未见新采样则作废（可能被校时）
const AI_JUDGE_OFFSET_KEY = "dida-ai-judge-clock-offset";
type AiJudgeOffsetEntry = { ahead: number; at: number }; // ahead=判题机领先本地毫秒；at=采样本地时间戳
const loadJudgeAhead = (judger: string): number => {
  try {
    const map = JSON.parse(localStorage.getItem(AI_JUDGE_OFFSET_KEY) ?? "{}") as Record<string, AiJudgeOffsetEntry>;
    const e = map[judger];
    if (!e) return 0;
    return Date.now() - e.at > 24 * 3600 * 1000 ? 0 : e.ahead;
  } catch {
    return 0;
  }
};
const saveJudgeAhead = (judger: string, ahead: number) => {
  try {
    if (!judger || !Number.isFinite(ahead)) return;
    const map = JSON.parse(localStorage.getItem(AI_JUDGE_OFFSET_KEY) ?? "{}") as Record<string, AiJudgeOffsetEntry>;
    const prev = map[judger];
    // 只保留历史最大采样：陈旧的 modify_time 只会得到偏差下界，越新越接近真实偏差
    if (prev && Number.isFinite(prev.ahead) && ahead <= prev.ahead) return;
    map[judger] = { ahead, at: Date.now() };
    localStorage.setItem(AI_JUDGE_OFFSET_KEY, JSON.stringify(map));
  } catch {
    // localStorage 不可用（隐私模式/禁用）时静默降级为会话内推算
  }
};

// 当前任务采用的判题机时钟偏差：拿到任务行后按 judger 从 localStorage 播种，此后每来一个更「新」的
// modify_time 就把测得上限值更新（只在偏差变大——即更接近真实值时更新，保证每秒轮询不抖动），
// 运行阶段耗时据此匀速前进，且刷新后归位真实历史耗时
const aiJudgeAhead = ref(0);
const aiJudgeKnown = ref(false);

// advanceAiNow 推进单调本地时钟：Date.now() 可能因系统校时（NTP/手动调整）回退，
// 导致耗时显示倒流；这里保证 aiNow 只增不减——正常每 100ms 前进，时钟回退时保持不动
const advanceAiNow = () => {
  aiLastWall = Math.max(aiLastWall, Date.now());
  aiNow.value = aiLastWall;
};

// 页面从后台恢复可见时立即刷新一次时间：浏览器会节流后台标签页的定时器，
// 不处理的话切回页面后耗时显示会有一段明显停滞
const handleAiVisibility = () => {
  if (document.visibilityState === "visible") {
    advanceAiNow();
  }
};

const stopAiTick = () => {
  if (aiTickTimer !== -1) {
    clearInterval(aiTickTimer);
    aiTickTimer = -1;
  }
  document.removeEventListener("visibilitychange", handleAiVisibility);
};

// running 时每 100ms tick，驱动「进行中」阶段耗时与 LLM 调用耗时按毫秒级刷新：
// 客户端以 insert_time/start_time 为锚点本地推算（无需等服务端轮询），
// 100ms 采样让 ms 单位的变化肉眼可见、更新节奏均匀；
// 之前 1s 采样叠加 3s 轮询重渲染，观感是忽快忽慢的跳动
watch(aiIsRunning, (running) => {
  if (running) {
    if (aiTickTimer === -1) {
      advanceAiNow();
      aiTickTimer = window.setInterval(() => {
        advanceAiNow();
      }, 100);
      document.addEventListener("visibilitychange", handleAiVisibility);
    }
  } else {
    stopAiTick();
  }
});

// 单调显示值缓存：键为展示项标识（llm:${id} / stage:${id}），值为该项已展示过的最大耗时。
// 客户端推算（本地时钟）与服务端落库值（服务端时钟）之间存在时钟偏差：
// running → success/fail 切换时若直接换用落库值，显示可能倒流。
// 不做精确时钟对齐，只以已展示最大值为下限，保证耗时只增不减
const aiDurationFloor = new Map<string, number>();

const monotonicDuration = (key: string, value: number) => {
  if (!Number.isFinite(value) || value < 0) value = 0;
  const floor = aiDurationFloor.get(key) ?? 0;
  const next = Math.max(floor, value);
  aiDurationFloor.set(key, next);
  return next;
};

// 行级锚点缓存：仅在「无服务端时钟可用」时兜底使用（running 行/阶段的起始锚点，ms）。
// 常规走 liveRunningMs 的服务端减法路径，无需此缓存；此处只是避免个别极端场景下负值长时间钳成 0ms
const aiAnchorMap = new Map<string, number>();

const liveRunningMs = (key: string, startMs: number) => {
  // 判题机时钟偏差路径（首选）：偏差已知且起始时间是判题机时钟时，
  // 用 aiNow + (判题机领先本地的偏差) 换算成判题机当前时间，running 耗时 = 换算后当前 - start_time。
  // 偏差只在新的 modify_time 到来且更大（更接近真实）时更新，更新之间保持恒定 → aiNow 每 100ms 单调前进，
  // 耗时匀速前进；刷新后从 localStorage 播种同一偏差，立即显示真实历史耗时，不受刷新/数据库落盘点影响
  if (aiJudgeKnown.value && Number.isFinite(startMs)) {
    return Math.max(0, aiNow.value + aiJudgeAhead.value - startMs);
  }
  // 兜底：未知偏差时回退到本地锚点（锚点取 min(起始时间, 首次渲染本地时间)，避免负值钳成 0）
  let anchor = aiAnchorMap.get(key);
  if (anchor === undefined) {
    anchor = Number.isFinite(startMs) ? Math.min(startMs, aiNow.value) : aiNow.value;
    aiAnchorMap.set(key, anchor);
  }
  return Math.max(0, aiNow.value - anchor);
};

// 把当前选中的 AI 任务同步到 URL 路径末段（…/judge/ai/:jobId），便于刷新/分享定位到指定历史任务。
// 复用 route.replace 不产生新历史记录，切换历史任务不会污染后退栈；
// 未选中任务（放弃/回到发起区）时删除该路径段，避免遗留已放弃任务的引用
const syncAiJobRoute = (jobId: number) => {
  const raw = route.params.jobId;
  const rawVal = Array.isArray(raw) ? raw[0] : raw;
  const current = rawVal == null ? 0 : Number(rawVal);
  if (current === jobId) return;
  const params = { ...route.params };
  if (jobId > 0) {
    params.jobId = String(jobId);
  } else {
    delete params.jobId;
  }
  router.replace({ name: "manage-problem-judge-ai", params });
};

// 切换/重置任务时清空单调缓存与判题机偏差采样标志（row id 全局唯一，这里只是保险，避免跨任务串号）
watch(aiSelectedJobId, () => {
  aiDurationFloor.clear();
  aiAnchorMap.clear();
  aiJudgeKnown.value = false;
  aiJudgeAhead.value = 0;
  syncAiJobRoute(aiSelectedJobId.value);
});

// 耗时格式化：<1s 用 ms，<60s 用 s，否则 min s
const formatDuration = (ms: number) => {
  if (!ms || ms <= 0) return "0ms";
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
  const min = Math.floor(ms / 60000);
  const sec = Math.round((ms % 60000) / 1000);
  return sec > 0 ? `${min}min ${sec}s` : `${min}min`;
};

// 阶段耗时：running 用锚点实时推算（客户端时钟偏差安全），否则用后端落库的 duration_ms；
// 经 monotonicDuration 保证切换时显示值不回退
const stageDuration = (st: AiTestdataStageView) => {
  const value = st.status === "running" ? liveRunningMs(`stage:${st.id}`, new Date(st.start_time).getTime()) : st.duration_ms;
  return formatDuration(monotonicDuration(`stage:${st.id}`, value));
};

// 心跳新鲜度：后端每完成一个测试点（或写入阶段文案）都会刷新 modify_time，
// 前端据此区分「正在推进」与「判题机可能已失联」（aiNow 每 100ms tick 驱动刷新）
const lastUpdateAgo = computed(() => {
  if (!aiJob.value?.modify_time) return "";
  const ms = aiNow.value - new Date(aiJob.value.modify_time).getTime();
  if (ms < 0) return "刚刚";
  return formatDuration(ms) + " 前";
});

// 认领时间（本地时区 HH:mm:ss）
const claimTimeText = computed(() => {
  if (!aiJob.value?.judge_time) return "";
  const d = new Date(aiJob.value.judge_time);
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleTimeString("zh-CN", { hour12: false });
});

// 应用=应用所有通过的测试点，失败的点无有效数据、自动剔除（dropKeys=全部失败点）
// 应用按钮禁用：没有任何通过的测试点时不允许应用
const aiApplyDisabled = computed(() => aiSuccessCount <= 0);

// 任务状态对应的 tag 主题：进行中 primary / 完成 success / 失败 danger / 取消 default
const jobTagTheme = (status: number) => {
  if (status === 7) return "success";
  if (status === 8) return "danger";
  return status === 9 ? "default" : "primary";
};

const aiJobTagTheme = computed(() => (aiJob.value ? jobTagTheme(aiJob.value.status) : "primary"));

// 历史任务时间（本地时区 MM-DD HH:mm）
const formatJobTime = (t?: string) => {
  if (!t) return "";
  const d = new Date(t);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString("zh-CN", {
    hour12: false,
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
};

const clearAiTimer = () => {
  if (aiTimer !== -1) {
    clearTimeout(aiTimer);
    aiTimer = -1;
  }
};

// 拉取任务状态，运行中则 1 秒后继续轮询
// aiFetchSeq 为世代计数：放弃任务/卸载组件时自增，使在途请求的过期响应作废
const fetchAiJob = async () => {
  clearAiTimer();
  if (aiSelectedJobId.value <= 0) return;
  const seq = ++aiFetchSeq;
  let res: any;
  try {
    res = await GetJudgeDataAi(aiSelectedJobId.value);
  } catch (e) {
    // 网络瞬时错误不能中断轮询链：静默排下一次，否则界面会永久冻结在旧状态
    console.error(e);
    if (seq !== aiFetchSeq) return;
    aiTimer = setTimeout(fetchAiJob, 3000);
    return;
  }
  // 过期响应（任务已被放弃或组件已卸载）直接丢弃，防止复活轮询
  if (seq !== aiFetchSeq) return;
  if (res.code !== 0) {
    // 运行中任务的瞬时错误不应永久中断轮询：静默排下一次；非运行中才提示并停止
    if (aiJob.value && aiJob.value.status <= 6) {
      aiTimer = setTimeout(fetchAiJob, 3000);
      return;
    }
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  // 捕获判题机时钟偏差：modify_time 即判题机写入的其本地当前时刻，与本地拉取时刻之差即两端时钟偏差。
  // 每次响应都重新测量，但偏差只在测得值更大（更新鲜、更接近真实偏差）时采用并持久化——
  // 既避免每 1s 轮询用陈旧 modify_time 重算导致的锯齿跳动，又保证首次播种/长期任务下逐步逼近真实偏差。
  const jobData = res.data as AiTestdataJobView;
  if (jobData.modify_time) {
    const measured = new Date(jobData.modify_time).getTime() - Date.now();
    const judger = jobData.judger ?? "";
    // 首个响应播种：localStorage 里该判题机的历史最大偏差可立即用于换算，让刷新后耗时归位真实历史值
    if (!aiJudgeKnown.value) {
      aiJudgeAhead.value = loadJudgeAhead(judger);
      aiJudgeKnown.value = true;
    }
    if (Number.isFinite(measured)) {
      const best = Math.max(aiJudgeAhead.value, measured);
      if (best !== aiJudgeAhead.value) {
        aiJudgeAhead.value = best;
        saveJudgeAhead(judger, best);
      }
    }
  }
  // 校验任务归属当前题目：URL/下拉传入的 jobId 若指向其他题目则视为任务不存在，
  // 防止跨题展示（含标程与预览）。理论上前端侧栏/新建只会在本题内产生 jobId。
  if (jobData.problem_id && jobData.problem_id !== problemId) {
    ShowTextTipsError(globalProperties, "任务不存在或不属于当前题目");
    aiFetchSeq++; // 作废后续轮询
    clearAiTimer();
    aiJob.value = null;
    aiSelectedJobId.value = 0; // watch 会同步清空路由 jobId，回到创建区
    return;
  }
  aiJob.value = jobData;
  // 同步刷新历史任务列表里当前任务的 status 标签（运行中也会变化）
  const listIdx = aiJobList.value.findIndex((j) => j.id === aiJob.value!.id);
  if (listIdx >= 0) {
    aiJobList.value[listIdx] = { ...aiJobList.value[listIdx], status: aiJob.value!.status };
  }
  if (aiJob.value.status <= 6) {
    // 1 秒轮询：新 LLM 调用行「首次出现」的延迟从 3 秒降到约 1 秒
    aiTimer = setTimeout(fetchAiJob, 1000);
  }
};

// 拉取历史 AI 生成任务列表，供侧栏/移动端选择器展示与切换。
// 不做自动选中：URL 无 jobId 时默认停留创建界面，查看历史/进行中任务需手动点开
const loadAiJobList = async () => {
  aiListLoading.value = true;
  try {
    const res = await GetJudgeDataAiList(problemId);
    if (res.code !== 0) return;
    aiJobList.value = (res.data as AiTestdataJobView[]) ?? [];
  } catch (e) {
    console.error(e);
    return;
  } finally {
    aiListLoading.value = false;
  }
};

const handleSelectAiJob = (v: any) => {
  const id = Number(v);
  if (id <= 0) {
    // 移动端下拉选择「＋ 新建生成任务」：回到创建界面
    handleNewAi();
    return;
  }
  aiSelectedJobId.value = id;
  fetchAiJob();
};

// 打开测试点失败详情弹窗：状态列只显示短标签，完整报错（沙箱状态/失败原因）点击后查看
const showAiTaskError = (row: any) => {
  aiErrorDialogTitle.value = `测试点 ${row.key} 失败详情`;
  const lines: string[] = [];
  if (row.purpose) lines.push(`用途：${row.purpose}`);
  lines.push(`状态：${row.status === "gen_fail" ? "生成失败（gen_fail）" : "运行失败（run_fail）"}`);
  if (row.sandbox_status) lines.push(`沙箱状态：${row.sandbox_status}`);
  if (row.fail_reason) lines.push(`失败原因：\n${row.fail_reason}`);
  aiErrorDialogText.value = lines.join("\n");
  aiErrorDialogVisible.value = true;
};

// 打开 LLM 调用失败详情弹窗：LLM 报错文本可能很长，同样点击查看完整内容
const showAiLlmError = (row: any) => {
  aiErrorDialogTitle.value = `LLM 调用失败详情（模型 ${row.model} · attempt ${row.attempt}）`;
  const lines: string[] = [];
  if (row.task_key) lines.push(`测试点：${row.task_key}`);
  if (row.error) lines.push(row.error);
  aiErrorDialogText.value = lines.join("\n") || "（无错误信息）";
  aiErrorDialogVisible.value = true;
};

// 下载 AI 预览测试数据 zip（后端返回预签名 URL）
const handleDownloadAiZip = async () => {
  if (aiFileExpired.value) {
    // 已标记过期：不再发起请求，直接提示用户重新生成
    ShowTextTipsError(globalProperties, "预览数据已过期，请重新生成");
    return;
  }
  aiDownloading.value = true;
  try {
    const res = await GetAiPreviewZip(aiSelectedJobId.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      // 100083：后端发现 R2 对象不存在并已标记过期，刷新任务状态让界面进入「已过期」展示
      if (res.code === 100083) {
        fetchAiJob();
      }
      return;
    }
    const url = res.data as string;
    if (url) {
      // 预签名 zip 为 application/zip：同窗口跳转触发下载，避免 async 回调里的 window.open 被 popup 拦截
      window.location.href = url;
    }
  } finally {
    aiDownloading.value = false;
  }
};

const handleStartAi = async () => {
  aiCreating.value = true;
  try {
    const res = await PostJudgeDataAi(problemId, aiHint.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    aiSelectedJobId.value = res.data.id;
    if (res.data.reused === true) {
      // 后端复用了该题已有的进行中任务，本次填写的提示词未生效
      ShowTextTipsError(globalProperties, "该题已有进行中的生成任务，已恢复其进度（本次填写的提示词未生效）");
    } else {
      ShowTextTipsSuccess(globalProperties, "生成任务已创建");
    }
    await fetchAiJob();
    // 刷新历史任务列表，让新任务出现在侧栏中
    loadAiJobList();
  } finally {
    aiCreating.value = false;
  }
};

const handleApplyAi = () => {
  aiApplyDialogVisible.value = true;
};

const handleConfirmApply = async () => {
  aiApplying.value = true;
  try {
    const res = await PostJudgeDataAiApply(aiSelectedJobId.value, aiFailedKeys.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      // 100083：预览数据已过期，刷新任务状态让界面进入「已过期」展示
      if (res.code === 100083) {
        fetchAiJob();
      }
      return;
    }
    aiApplyDialogVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "已应用为官方测试数据");
    aiJob.value = null;
    aiSelectedJobId.value = 0;
    // 刷新历史任务列表：自动选中最近一条（即刚应用的这条），展示「已应用」状态
    await loadAiJobList();
  } finally {
    aiApplying.value = false;
  }
};

// 新建生成任务：清空当前选中回到发起区（不取消任何任务，进行中的生成继续在后台跑，
// 由后端 CreateJob 在发起时自动选择复用或新开）
const handleNewAi = () => {
  aiFetchSeq++; // 使在途请求作废，防止旧任务响应复活
  clearAiTimer();
  aiJob.value = null;
  aiSelectedJobId.value = 0;
};

// 放弃当前任务：通知后端取消（停止流水线与 LLM 开销、释放判题机槽位），
// 并清空展示回到发起区（不自动发起，供修改提示语后手动开始生成）
const handleResetAi = async () => {
  aiFetchSeq++; // 使在途请求作废，防止过期响应复活已放弃的任务
  clearAiTimer();
  if (aiSelectedJobId.value > 0) {
    try {
      await PostJudgeDataAiCancel(aiSelectedJobId.value);
    } catch (e) {
      // 取消失败不阻塞本地界面重置（任务可能已结束）
      console.error(e);
    }
  }
  aiJob.value = null;
  aiSelectedJobId.value = 0;
};

// 放弃并重新生成：先取消旧任务，再用当前提示语立即发起一次新的生成
const handleRestartAi = async () => {
  await handleResetAi();
  handleStartAi();
};

// 在当前任务上继续生成：不新开任务，把原任务重置回待认领，
// 判题机在原有时间线上追加新一轮生成（复用规划/标程/已通过测试点）。
// retryKeys 为本次要重新生成的测试点；为空表示重试全部失败的点
const handleRetryAi = async (retryKeys: string[] | null = null) => {
  if (aiSelectedJobId.value <= 0) return;
  aiCreating.value = true;
  try {
    const res = await PostJudgeDataAiRetry(aiSelectedJobId.value, retryKeys ?? []);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    // 续跑沿用同一任务 id，时间线向后扩展
    aiSelectedJobId.value = res.data.id;
    ShowTextTipsSuccess(globalProperties, "已在当前任务上继续生成，时间线将向后扩展（复用规划、参考代码与已通过测试点）");
    await fetchAiJob();
    loadAiJobList();
  } finally {
    aiCreating.value = false;
  }
};

// AI 任务表格的文件元数据列（与评测数据页的官方任务表格同构）
const aiFileColumns = [
  {
    title: "分数",
    colKey: "score",
    width: 70,
  },
  {
    title: "输入文件",
    colKey: "inFile",
  },
  {
    title: "输入文件大小",
    colKey: "inFileSize",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.inFileSize);
    },
  },
  {
    title: "输出文件",
    colKey: "outFile",
  },
  {
    title: "输出文件大小",
    colKey: "outFileSize",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.outFileSize);
    },
  },
  {
    title: "输出限制",
    colKey: "outLimit",
    cell: (_: any, data: any) => {
      return GetFileSizeStr(data.row.outLimit);
    },
  },
];

const aiTaskTableColumns = computed(() => {
  const cols: any[] = [
    { title: "测试点", colKey: "key", width: 70 },
    { title: "用途", colKey: "purpose" },
    {
      title: "状态",
      colKey: "status",
      width: 110,
      cell: (_: any, data: any) => {
        const row = data.row;
        if (row.status === "accepted") {
          return (
            <t-tag theme="success" variant="light">
              通过
            </t-tag>
          );
        }
        // 失败时仅展示短标签，完整报错点击弹窗查看，避免长报错文本撑宽表格
        const label = row.status === "run_fail" ? "运行失败" : "生成失败";
        return (
          <t-tooltip content="点击查看详情">
            <span class="dida-ai-fail-tag" onClick={() => showAiTaskError(row)}>
              <t-tag theme="danger" variant="light">
                {label}
              </t-tag>
              <t-icon name="browse" size="14px" style={{ color: "#999" }} />
            </span>
          </t-tooltip>
        );
      },
    },
    ...aiFileColumns,
  ];
  if (isMobile.value) {
    return cols.filter((c) => c.colKey !== "purpose" && c.colKey !== "inFileSize" && c.colKey !== "outFileSize");
  }
  return cols;
});

// LLM 调用明细列
const llmCallColumns: any[] = [
  { title: "模型", colKey: "model", width: 140 },
  { title: "attempt", colKey: "attempt", width: 90 },
  {
    title: "耗时",
    colKey: "duration_ms",
    width: 100,
    cell: (_: any, data: any) => {
      const row = data.row;
      // running 行用锚点实时推算（客户端时钟偏差安全，aiNow 每 100ms tick 刷新），
      // 结束行用服务端落库值；经 monotonicDuration 保证切换时显示值不回退
      const value =
        row.status === "running" && row.insert_time ? liveRunningMs(`llm:${row.id}`, new Date(row.insert_time).getTime()) : row.duration_ms;
      return formatDuration(monotonicDuration(`llm:${row.id}`, value));
    },
  },
  {
    title: "token",
    colKey: "tokens",
    cell: (_: any, data: any) => {
      const total = data.row.prompt_tokens + data.row.completion_tokens;
      return (
        <t-tooltip content={`输入 ${data.row.prompt_tokens} / 输出 ${data.row.completion_tokens}`}>
          <span>{total}</span>
        </t-tooltip>
      );
    },
  },
  {
    title: "状态",
    colKey: "status",
    width: 90,
    cell: (_: any, data: any) => {
      const s = data.row.status;
      const theme = s === "success" ? "success" : s === "fail" ? "danger" : "primary";
      return (
        <t-tag size="small" variant="light" theme={theme}>
          {s}
        </t-tag>
      );
    },
  },
  {
    title: "错误",
    colKey: "error",
    cell: (_: any, data: any) => {
      const err = data.row.error;
      if (!err) return <span style="color: #999">—</span>;
      // 错误明细可能很长（LLM 报错/沙箱输出摘要），表格内仅展示短标签，点击弹窗查看完整内容
      return (
        <t-tooltip content="点击查看详情">
          <span class="dida-ai-fail-tag" onClick={() => showAiLlmError(data.row)}>
            <t-tag size="small" theme="danger" variant="light">
              错误
            </t-tag>
            <t-icon name="browse" size="14px" style={{ color: "#999" }} />
          </span>
        </t-tooltip>
      );
    },
  },
];

// t-table 的 cell 渲染函数不会随组件外部 ref（如 aiNow）自动重渲染：
// 数据数组引用不变时 Vue 会跳过子组件更新，running 行的耗时因此冻结。
// 这里在存在 running 行时克隆行对象（新身份强制 t-table 重渲染 cell），
// 配合 aiStages 的 tick 重建，让耗时随 100ms tick 实时跳动；
// 全部调用结束后复用原引用，避免无谓重渲染
const liveLlmCalls = (calls?: AiTestdataLlmCallView[]) => {
  void aiNow.value; // 依赖 aiNow：每次 tick 都会重新执行本函数
  if (!calls) return [];
  if (!calls.some((c) => c.status === "running")) return calls;
  return calls.map((c) => ({ ...c }));
};

onBeforeUnmount(() => {
  aiFetchSeq++; // 使在途请求作废，防止卸载后轮询泄漏
  clearAiTimer();
  stopAiTick();
});

// ===== 页面跳转 =====
const handleBack = () => {
  router.push({
    name: "manage-problem-judge",
    params: {
      problemKey: problemKey.value,
    },
  });
};

const handleClickView = () => {
  router.push({
    name: "problem-detail",
    params: {
      problemKey: problemKey.value,
    },
  });
};

// 精简加载题目：只取 id / 标题 / 权限 / AI 开关，以及最近一次任务 id（进行中继续轮询）
const loadProblem = async () => {
  const res = await GetProblemJudge(problemKey.value);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    await router.push({ name: "problem" });
    return;
  }

  const problem = res.data.problem;
  problemId = problem.id;
  problemTitle.value = problem.title;
  aiEnabled.value = res.data.ai_enabled === true;

  webStyleStore.setTitle(problem.title + " - AI 生成测试数据");

  problemLoading.value = false;
};

onMounted(async () => {
  if (Array.isArray(route.params.problemKey)) {
    problemKey.value = route.params.problemKey[0];
  } else {
    problemKey.value = route.params.problemKey;
  }
  if (!problemKey.value) {
    ShowTextTipsError(globalProperties, "题目不存在");
    await router.push({ name: "problem" });
    return;
  }

  problemLoading.value = true;
  // 从 URL 路径恢复指定历史任务（…/judge/ai/:jobId，便于刷新/分享定位到某一任务）。
  // 无 jobId 时不做自动选中（默认停留创建界面），仅当路径显式指定了任务才恢复展示
  const rawJob = route.params.jobId;
  const rawJobVal = Array.isArray(rawJob) ? rawJob[0] : rawJob;
  const urlJobId = rawJobVal == null ? 0 : Number(rawJobVal);
  if (Number.isInteger(urlJobId) && urlJobId > 0) {
    aiSelectedJobId.value = urlJobId;
  }
  await loadProblem();
  // 拉取历史任务列表，供侧栏/移动端选择器展示与切换
  if (aiEnabled.value && problemId > 0) {
    await loadAiJobList();
  }
  // URL 指定任务时 loadProblem/loadAiJobList 均不自动拉取，这里补一次，保证刷新/分享进来即展示该任务
  if (aiSelectedJobId.value > 0 && !aiJob.value) {
    await fetchAiJob();
  }
});
</script>

<template>
  <t-loading :loading="problemLoading">
    <div class="dida-ai-page">
      <!-- 页头：返回入口 + 题目标题 + 当前任务状态 -->
      <div class="dida-ai-header">
        <t-button variant="text" theme="primary" @click="handleBack">
          <template #icon><t-icon name="chevron-left" /></template>
          返回评测数据
        </t-button>
        <span class="dida-ai-header-title" @click="handleClickView">{{ problemTitle }}</span>
        <t-tag v-if="aiJob" size="small" :theme="aiJobTagTheme" variant="light"> #{{ aiJob.id }} · {{ aiStatusName }} </t-tag>
      </div>

      <!-- 功能开关拦截（页面访问权限由路由 auths 与全局 View403 兜底） -->
      <t-card v-if="!problemLoading && !aiEnabled" class="dida-ai-card">
        <t-alert theme="warning" message="本题尚未开启 AI 生成测试数据功能。" />
      </t-card>

      <t-row v-else :gutter="[16, 16]">
        <!-- 主工作区 -->
        <t-col :span="isMobile ? 12 : 8">
          <div class="dida-ai-main">
            <!-- 移动端：历史任务选择器 -->
            <t-select
              v-if="isMobile && aiJobList.length > 0"
              :value="aiSelectedJobId"
              @change="handleSelectAiJob"
              placeholder="选择历史生成任务"
              class="dida-ai-mobile-select"
            >
              <t-option :value="0" label="＋ 新建生成任务" />
              <t-option v-for="job in aiJobList" :key="job.id" :value="job.id" :label="`#${job.id} · ${AI_STATUS_NAMES[job.status] ?? '未知'}`" />
            </t-select>

            <!-- 生成任务工作台 -->
            <t-card class="dida-ai-card" title="生成任务">
              <!-- 生成时的提示词：发起区输入框即为当前提示，故仅选中任务后展示 -->
              <div v-if="aiJob && aiJob.hint" class="dida-ai-hint">生成要求：{{ aiJob.hint }}</div>
              <!-- 发起区：无任务时 -->
              <div v-if="!aiJob">
                <t-alert
                  theme="info"
                  message="AI 将阅读题面，规划测试点并撰写参考代码，在沙箱中运行产出标准输出。生成结果需人工确认后才会生效。"
                  style="margin-bottom: 12px"
                />
                <t-space direction="vertical" style="width: 100%">
                  <t-textarea
                    v-model="aiHint"
                    placeholder="可选：生成要求，如「覆盖 n=1 与 n=10^5 边界，包含链状数据，生成 12 个测试点」"
                    :autosize="{ minRows: 3, maxRows: 6 }"
                  />
                  <div class="dida-ai-presets">
                    <span class="dida-ai-presets-label">快捷预设：</span>
                    <t-tag
                      v-for="preset in hintPresets"
                      :key="preset.label"
                      variant="outline"
                      class="dida-ai-preset"
                      @click="applyHintPreset(preset.text)"
                    >
                      {{ preset.label }}
                    </t-tag>
                  </div>
                  <t-button theme="primary" block @click="handleStartAi" :loading="aiCreating"> 开始生成 </t-button>
                </t-space>
              </div>

              <!-- 进度区：任务进行中 -->
              <div v-else-if="aiIsRunning">
                <t-space direction="vertical" style="width: 100%">
                  <div class="dida-ai-status-row">
                    <t-tag theme="primary" variant="light">{{ aiStatusName }}</t-tag>
                    <span class="dida-ai-stage-msg">{{ aiJob?.stage_message }}</span>
                  </div>
                  <!-- 队列与心跳信息：判断任务是否在推进、由谁处理 -->
                  <div class="dida-ai-meta">
                    <template v-if="aiJob?.judger">判题机 {{ aiJob.judger }}</template>
                    <template v-if="claimTimeText"> · 认领于 {{ claimTimeText }}</template>
                    <template v-if="lastUpdateAgo"> · 最后更新 {{ lastUpdateAgo }}</template>
                  </div>
                  <t-progress v-if="(aiJob?.task_total ?? 0) > 0" :percentage="aiProgressPercent" status="active" />
                  <div class="dida-ai-meta">生成在后台持续进行，可安全离开本页，稍后返回自动恢复进度。</div>
                  <t-button theme="default" @click="handleResetAi">放弃</t-button>
                </t-space>
              </div>

              <!-- 失败区 -->
              <div v-else-if="aiJob?.status === 8">
                <t-alert theme="error" :message="'生成失败：' + (aiJob?.stage_message ?? '')" />
                <t-space style="margin-top: 12px" :break-line="isMobile">
                  <t-button theme="primary" @click="handleRetryAi()" :loading="aiCreating"> 继续生成（复用规划与标程，扩展时间线） </t-button>
                  <t-button theme="default" @click="handleRestartAi">全新生成</t-button>
                </t-space>
              </div>

              <!-- 已取消区 -->
              <div v-else-if="aiJob?.status === 9">
                <t-alert theme="default" message="该生成任务已被取消，可以重新发起新的生成。" />
                <t-button theme="default" @click="handleRestartAi" style="margin-top: 12px"> 重新发起 </t-button>
              </div>

              <!-- 预览区：已完成（待应用或已应用，均展示完整预览详情） -->
              <div v-else-if="aiIsFinished">
                <t-space direction="vertical" style="width: 100%">
                  <!-- 过期：预览 zip 已被清理，无法应用/下载，需在本任务上重新生成全部测试点 -->
                  <t-alert
                    v-if="aiFileExpired"
                    theme="error"
                    message="预览数据已过期（存储对象已被清理），无法应用与下载；可点击「重新生成全部测试点」在本次任务上重新生成。"
                  />
                  <t-alert v-else-if="aiHasFailedTasks" theme="warning" :message="`部分测试点生成失败（${aiSuccessCount}/${aiTasks.length} 成功）`" />

                  <t-collapse>
                    <t-collapse-panel v-if="aiJob?.result?.reference_code" header="参考代码">
                      <pre class="dida-ai-code">{{ aiJob?.result?.reference_code }}</pre>
                    </t-collapse-panel>
                    <t-collapse-panel v-if="aiJob?.result?.compile_message" header="编译信息">
                      <pre class="dida-ai-code">{{ aiJob?.result?.compile_message }}</pre>
                    </t-collapse-panel>
                  </t-collapse>

                  <t-table
                    :data="aiTasks"
                    :columns="aiTaskTableColumns"
                    row-key="key"
                    vertical-align="top"
                    table-layout="auto"
                    :scroll="{ x: 'max-content' }"
                  />

                  <t-space :break-line="isMobile">
                    <t-button theme="primary" :disabled="aiApplyDisabled || aiFileExpired" @click="handleApplyAi">
                      应用为官方测试数据（通过 {{ aiSuccessCount }}/{{ aiTasks.length }}）
                    </t-button>
                    <t-button theme="default" :disabled="aiFileExpired" @click="handleDownloadAiZip" :loading="aiDownloading">
                      {{ aiFileExpired ? "数据已过期" : "下载测试数据" }}
                    </t-button>
                    <!-- 未过期：重试作用域为全部失败测试点（复用已通过点，扩展当前时间线） -->
                    <t-button
                      v-if="aiHasFailedTasks && !aiFileExpired"
                      theme="warning"
                      :disabled="aiFailedKeys.length === 0"
                      @click="handleRetryAi(aiFailedKeys)"
                      :loading="aiCreating"
                    >
                      重试失败测试点（{{ aiFailedKeys.length }}）
                    </t-button>
                    <!-- 已过期：已通过点的预览数据也已丢失，无法只重试失败点，
                         需重新生成全部测试点（后端会把 keys 扩展为全部规划点） -->
                    <t-button
                      v-if="aiFileExpired"
                      theme="warning"
                      @click="handleRetryAi(aiTasks.map((t) => t.key))"
                      :loading="aiCreating"
                    >
                      重新生成全部测试点
                    </t-button>
                  </t-space>
                  <div v-if="aiApplyDisabled && !aiFileExpired" class="dida-ai-meta">至少 1 个测试点通过才能应用。</div>
                  <div v-if="aiFileExpired" class="dida-ai-meta">预览数据已过期，无法应用与下载；可点击「重新生成全部测试点」重新生成。</div>
                </t-space>
              </div>
            </t-card>

            <!-- 阶段时间线（可观测性：生成各阶段与 LLM 调用明细） -->
            <t-card v-if="aiStages.length > 0" class="dida-ai-card" title="生成时间线">
              <t-timeline>
                <t-timeline-item v-for="st in aiStages" :key="st.id" :label="AI_STATUS_NAMES[st.stage] ?? '阶段'">
                  <div style="font-size: 12px; color: #666">
                    <t-tag size="small" :theme="st.status === 'success' ? 'success' : st.status === 'fail' ? 'danger' : 'primary'" variant="light">
                      {{ st.status }}
                    </t-tag>
                    <span style="margin-left: 6px">{{ stageDuration(st) }}</span>
                    <span v-if="st.message" style="margin-left: 6px; color: #999">{{ st.message }}</span>
                  </div>
                  <t-collapse v-if="st.llm_calls?.length" style="margin-top: 4px">
                    <t-collapse-panel :header="`LLM 调用（${st.llm_calls.length} 次）`">
                      <t-table
                        :data="liveLlmCalls(st.llm_calls)"
                        :columns="llmCallColumns"
                        row-key="id"
                        size="small"
                        vertical-align="top"
                        table-layout="auto"
                        :scroll="{ x: 'max-content' }"
                      />
                    </t-collapse-panel>
                  </t-collapse>
                </t-timeline-item>
              </t-timeline>
            </t-card>
          </div>
        </t-col>

        <!-- 侧栏：桌面端历史任务 + 题目信息 + 使用说明 -->
        <t-col :span="isMobile ? 12 : 4">
          <div class="dida-ai-side" :class="{ 'dida-ai-side-sticky': !isMobile }">
            <t-card v-if="!isMobile" class="dida-ai-card" title="历史任务">
              <template #actions>
                <t-button variant="text" size="small" @click="handleNewAi"> 新建 </t-button>
              </template>
              <div v-if="aiJobList.length === 0" class="dida-ai-empty">暂无历史任务，从左侧发起第一次生成</div>
              <div v-else class="dida-ai-job-list">
                <div
                  v-for="job in aiJobList"
                  :key="job.id"
                  class="dida-ai-job-item"
                  :class="{ 'dida-ai-job-item-active': job.id === aiSelectedJobId }"
                  @click="handleSelectAiJob(job.id)"
                >
                  <t-tag size="small" :theme="jobTagTheme(job.status)" variant="light">
                    #{{ job.id }} · {{ AI_STATUS_NAMES[job.status] ?? "未知" }}
                  </t-tag>
                  <span class="dida-ai-job-time">{{ formatJobTime(job.modify_time) }}</span>
                </div>
              </div>
            </t-card>

            <t-card class="dida-ai-card" title="题目">
              <div class="dida-ai-problem-title" @click="handleClickView">{{ problemTitle }}</div>
              <t-space style="margin-top: 12px">
                <t-button size="small" variant="outline" @click="handleClickView">查看题目</t-button>
                <t-button size="small" variant="outline" @click="handleBack">评测数据</t-button>
              </t-space>
            </t-card>

            <t-card v-if="!isMobile" class="dida-ai-card" title="使用说明">
              <div class="dida-ai-guide">
                <p>1. 填写可选的生成要求，点击「开始生成」；</p>
                <p>2. AI 将阅读题面、规划测试点、撰写并编译参考代码，在沙箱中生成标准输出；</p>
                <p>3. 生成完成后人工确认，点击「应用为官方测试数据」应用所有通过的测试点（失败的点自动剔除）；</p>
                <p>4. 测试点失败时点击「重试失败测试点」继续生成：重试会在当前任务上扩展时间线，并保留已通过的测试点，不会新开任务；</p>
                <p>5. 预览数据可能因存储清理而过期，过期后需重新生成。</p>
                <p>应用会替换当前官方测试数据，spj 与模板文件自动继承。</p>
              </div>
            </t-card>
          </div>
        </t-col>
      </t-row>
    </div>
  </t-loading>

  <!-- 失败详情弹窗：状态列/错误列点击短标签后展示完整报错 -->
  <t-dialog v-model:visible="aiErrorDialogVisible" :header="aiErrorDialogTitle" :footer="false" :width="isMobile ? '90%' : '640px'">
    <pre class="dida-ai-error-detail">{{ aiErrorDialogText }}</pre>
  </t-dialog>

  <t-dialog
    v-model:visible="aiApplyDialogVisible"
    header="确认应用为官方测试数据"
    :confirm-btn="{ content: '确认应用', loading: aiApplying, theme: 'danger' }"
    @confirm="handleConfirmApply"
  >
    <div>
      <p>此操作将<strong>替换</strong>本题当前的官方测试数据：</p>
      <ul style="font-size: 13px; color: #666">
        <li>
          应用 {{ aiSuccessCount }} 个通过的测试点（失败 {{ aiFailedKeys.length }} 个自动剔除），分数自动均分为 1000 分制（原有自定义分值将被覆盖）；
        </li>
        <li>原题的特判程序（spj）与模板文件（template）会自动继承，无需重新上传；</li>
        <li>历史提交如需按新数据计算结果，请自行重判。</li>
      </ul>
    </div>
  </t-dialog>
</template>

